-- Chronos schema left by the FIRST start of 0.2.0-0.2.5 on an empty database outside the
-- Linux image (Windows, pip): chained_job_events lacks webhook_timeout_seconds and trigger_flows
-- lacks routing. Generated by one app startup of git tag release-0.2.5 on an empty database.
-- Used by tests/test_schema_upgrade.py as an upgrade starting point; do not edit by hand.

CREATE TABLE chained_job_events (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                parent_job_id INTEGER NOT NULL REFERENCES scheduled_jobs(id) ON DELETE CASCADE,
                position INTEGER NOT NULL,
                task_type VARCHAR NOT NULL,
                pipeline_id VARCHAR NOT NULL,
                entity_ids TEXT,
                group_ids TEXT,
                with_snapshot BOOLEAN NOT NULL DEFAULT 0,
                snapshot_write_method VARCHAR NOT NULL DEFAULT 'UPSERT',
                execution_mode VARCHAR NOT NULL DEFAULT 'async',
                created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
            , agent_id VARCHAR, query_sql TEXT, saved_query_id VARCHAR, query_read_only BOOLEAN NOT NULL DEFAULT 1);

CREATE TABLE scheduled_jobs (
	id INTEGER NOT NULL, 
	name VARCHAR NOT NULL, 
	description VARCHAR, 
	task_type VARCHAR(26) NOT NULL, 
	cron_expression VARCHAR NOT NULL, 
	pipeline_id VARCHAR NOT NULL, 
	entity_ids TEXT, 
	group_ids TEXT, 
	with_snapshot BOOLEAN, 
	snapshot_write_method VARCHAR NOT NULL, 
	agent_id VARCHAR, 
	query_sql TEXT, 
	saved_query_id VARCHAR, 
	query_read_only BOOLEAN NOT NULL, 
	enabled BOOLEAN, 
	command TEXT NOT NULL, 
	cron_job_identifier VARCHAR NOT NULL, 
	created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, 
	last_run DATETIME, 
	next_run DATETIME, 
	last_successful_run DATETIME, 
	last_error_message TEXT, 
	last_run_error_time DATETIME, 
	start_time VARCHAR, 
	timezone_name VARCHAR, 
	is_cron_expression BOOLEAN NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (cron_job_identifier)
);

CREATE TABLE settings (
	id INTEGER NOT NULL, 
	"key" VARCHAR NOT NULL, 
	value VARCHAR, 
	description VARCHAR, 
	created_at DATETIME NOT NULL, 
	updated_at DATETIME NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE trigger_flow_events (
                    id                   INTEGER PRIMARY KEY AUTOINCREMENT,
                    trigger_flow_id      INTEGER NOT NULL
                                             REFERENCES trigger_flows(id) ON DELETE CASCADE,
                    position             INTEGER NOT NULL,
                    task_type            VARCHAR NOT NULL,
                    pipeline_id          VARCHAR NOT NULL,
                    entity_ids           TEXT,
                    group_ids            TEXT,
                    with_snapshot        BOOLEAN NOT NULL DEFAULT 0,
                    snapshot_write_method VARCHAR NOT NULL DEFAULT 'UPSERT',
                    execution_mode       VARCHAR NOT NULL DEFAULT 'async',
                    created_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    updated_at           TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
                , agent_id VARCHAR, query_sql TEXT, saved_query_id VARCHAR, query_read_only BOOLEAN NOT NULL DEFAULT 1);

CREATE TABLE trigger_flow_execution_logs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    trigger_flow_id INTEGER NOT NULL,
                    status VARCHAR NOT NULL,
                    source VARCHAR,
                    error_message TEXT,
                    duration_ms INTEGER,
                    triggered_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (trigger_flow_id) REFERENCES trigger_flows(id) ON DELETE CASCADE
                );

CREATE TABLE trigger_flows (
                    id                      INTEGER PRIMARY KEY AUTOINCREMENT,
                    name                    VARCHAR NOT NULL,
                    description             VARCHAR,
                    enabled                 BOOLEAN NOT NULL DEFAULT 1,
                    secret_token            VARCHAR NOT NULL,
                    last_triggered          TIMESTAMP,
                    last_successful_trigger TIMESTAMP,
                    last_error_message      TEXT,
                    last_trigger_error_time TIMESTAMP,
                    created_at              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
                    updated_at              TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
                , platform_event VARCHAR);

CREATE INDEX ix_chained_job_events_parent_job_id ON chained_job_events (parent_job_id);

CREATE INDEX ix_scheduled_jobs_id ON scheduled_jobs (id);

CREATE INDEX ix_settings_id ON settings (id);

CREATE UNIQUE INDEX ix_settings_key ON settings ("key");

CREATE INDEX ix_trigger_flow_events_flow_id ON trigger_flow_events (trigger_flow_id);

CREATE INDEX ix_trigger_flow_execution_logs_trigger_flow_id ON trigger_flow_execution_logs (trigger_flow_id);
